package me.rerere.rikkahub.data.render

internal val musicRendererSpecs = listOf(
    RendererSpec("mei", "MEI / early music", "MEI XML with the MEI namespace (not MusicXML)",
        MEI_MENSURAL_EXAMPLE, setOf("mei", "mei-xml"), maxChars = MAX_SCORE_SOURCE_CHARS,
        notes = "Local Verovio 6.4.1, isolated disposable WASM Worker. MEI modern notation, mensural.white/mensural.black and neume encodings; not a facsimile image viewer or complete MEI validator. Neume syllable lyrics are currently retained in source with an explicit preview notice, not engraved or included in PDF; provide a readable lyric transcription alongside the score. One mdiv, namespace http://www.music-encoding.org/ns/mei. At most 16000 note/rest/nc events, 64 pages, 15-second layout timeout. No external facsimiles, links, DTD/entities or arbitrary scripts. Paginated preview and whole-score vector PDF; original MEI retained. User may disable this renderer. Does not infer/transcribe historic notation or play audio."),
)

internal const val MEI_MENSURAL_EXAMPLE = """<mei xmlns="http://www.music-encoding.org/ns/mei" meiversion="5.0"><meiHead><fileDesc><titleStmt><title>Mensural example</title></titleStmt><pubStmt/></fileDesc></meiHead><music><body><mdiv><score><scoreDef><staffGrp><staffDef n="1" lines="5" notation.type="mensural.white" clef.shape="C" clef.line="3"><mensur sign="O" tempus="3" prolatio="2"/></staffDef></staffGrp></scoreDef><section><staff n="1"><layer n="1"><note pname="c" oct="4" dur="brevis"/><note pname="d" oct="4" dur="semibrevis"/><note pname="e" oct="4" dur="minima"/><note pname="f" oct="4" dur="minima"/><note pname="d" oct="4" dur="semibrevis"/></layer></staff></section></score></mdiv></body></music></mei>"""

internal const val MEI_NEUME_EXAMPLE = """<mei xmlns="http://www.music-encoding.org/ns/mei" meiversion="5.0"><meiHead><fileDesc><titleStmt><title>Chant example</title></titleStmt><pubStmt/></fileDesc></meiHead><music><body><mdiv><score><scoreDef><staffGrp><staffDef n="1" lines="4" notation.type="neume" clef.shape="C" clef.line="3"/></staffGrp></scoreDef><section><staff n="1"><layer n="1"><syllable><syl>Ky</syl><neume><nc pname="c" oct="4"/><nc pname="d" oct="4"/></neume></syllable><syllable><syl>ri</syl><neume><nc pname="e" oct="4"/></neume></syllable><syllable><syl>e</syl><neume><nc pname="d" oct="4"/><nc pname="c" oct="4"/></neume></syllable></layer></staff></section></score></mdiv></body></music></mei>"""
